#include <stdio.h>

#define BUF_SIZE 4096

static unsigned char is_ws[256];

static int is_any_ws(unsigned char b)
{
    return is_ws[b];
}

int main(void)
{
    unsigned char buf[BUF_SIZE];
    int lines = 0, words = 0, bytes_count = 0;
    int maxlen = 0, curline = 0;
    int in_word = 0;
    size_t n;

    /* Setup whitespace lookup table */
    for (int i = 0; i < 256; i++)
        is_ws[i] = 0;
    is_ws[' ']     = 1;
    is_ws['\t']    = 1;
    is_ws['\n']    = 1;
    is_ws['\v']    = 1;
    is_ws['\f']    = 1;
    is_ws['\r']    = 1;

    while ((n = fread(buf, 1, BUF_SIZE, stdin)) > 0) {
        for (size_t i = 0; i < n; i++) {
            unsigned char b = buf[i];
            bytes_count++;

            if (b == '\n') {
                if (curline > maxlen)
                    maxlen = curline;
                lines++;
                curline = 0;
                /* \n is whitespace, so it can end a word */
                if (in_word) {
                    words++;
                    in_word = 0;
                }
            } else if (is_any_ws(b)) {
                /* not '\n' but still whitespace (\r or others) - ends word */
                if (in_word) {
                    words++;
                    in_word = 0;
                }
                curline++;
            } else {
                /* a non-whitespace byte */
                curline++;
                if (!in_word)
                    in_word = 1;
            }
        }
        bytes_count += (int)n - (int)(n > 0 ? 0 : 0);
    }

    /* If there's any remaining content on the last line (no trailing \n) */
    if (curline > maxlen)
        maxlen = curline;

    printf("%d %d %d %d\n", lines, words, bytes_count, maxlen);

    return 0;
}

